<body><main class="shell"><section class="panel"><a class="brand" href="{{ route('customer.dashboard') }}"><img src="{{ asset('assets/logo/logo.png') }}" alt="EcoCraft"><span>EcoCraft · {{ $role === 'admin' ? 'Admin' : 'Seller' }}</span></a><div class="eyebrow">{{ $title }}</div><h1>{{ $heading }}</h1><p class="lead">{{ $lead }}</p>@if(session('success'))<div class="alert" style="background:#e5f3e9;color:#1e4b38">{{ session('success') }}</div>@endif @if($errors->any())<div class="alert"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form method="POST" action="{{ $action }}">@csrf<div class="field"><label for="email">Email</label><input id="email" type="email" name="email" value="{{ old('email') }}" required autofocus></div><div class="field"><label for="password">Kata sandi</label><input id="password" type="password" name="password" required></div><button class="btn" type="submit">Masuk sebagai {{ $role === 'admin' ? 'Admin' : 'Seller' }}</button></form>@if(!empty($registerUrl))<div class="footer">Belum punya akun? <a href="{{ $registerUrl }}">Daftar {{ $role === 'admin' ? 'admin' : 'seller' }}</a></div>@endif</section><aside class="art"><div><h2>{{ $role === 'admin' ? 'Kurasi dengan teliti.' : 'Jual dengan makna.' }}</h2><p>{{ $role === 'admin' ? 'Pastikan setiap karya yang hadir di EcoCraft tetap terpercaya dan berdampak.' : 'Bawa karya lokal dan material berkelanjutanmu ke komunitas EcoCraft.' }}</p></div></aside></main></body>
